+                        inputClientInfo.config.inputAttribute.IsSecurityImeFlag();
+    if (isOneTimeCode) {
+        IMSA_HILOGI("StylusActivation, is one time code or security input, not start stylus ime.");
+    }
+    return isOneTimeCode;
+}
